from pathlib import Path
import base64

FILES = {'apps/dashboard/workbench.py': '', 'apps/dashboard/smart_workbook.py': '', 'apps/dashboard/views.py': '', 'apps/dashboard/urls.py': '', 'templates/base.html': '', 'templates/dashboard/mockup_shell.html': 'eyUgZXh0ZW5kcyAiYmFzZS5odG1sIiAlfQo=', 'templates/dashboard/entity_list.html': '', 'templates/dashboard/entity_detail.html': '', 'templates/dashboard/entity_form.html': '', 'templates/dashboard/organization.html': '', 'templates/dashboard/smart_workbook.html': '', 'templates/dashboard/annex_controls.html': '', 'templates/dashboard/document_detail.html': '', 'templates/accounts/user_list.html': '', 'static/css/product_v64.css': ''}

for filename, encoded in FILES.items():
    path = Path(filename)
    path.parent.mkdir(parents=True, exist_ok=True)

    if path.exists():
        backup = path.with_name(path.name + ".before_v64.bak")
        if not backup.exists():
            backup.write_text(
                path.read_text(encoding="utf-8"),
                encoding="utf-8",
            )

    path.write_bytes(
        base64.b64decode(encoded)
    )

    print("OK:", filename)

# Context processor global: keep only one navigation source.
settings = Path("config/settings/base.py")
text = settings.read_text(encoding="utf-8")
backup = settings.with_name(
    settings.name + ".before_v64.bak"
)

if not backup.exists():
    backup.write_text(
        text,
        encoding="utf-8",
    )

cp = '"apps.dashboard.context_processors.sgsi_navigation",'

if cp not in text:
    anchor = '"django.contrib.messages.context_processors.messages",'

    if anchor not in text:
        raise SystemExit(
            "ERROR: no se encontró messages context processor."
        )

    text = text.replace(
        anchor,
        anchor + "\n                " + cp,
        1,
    )

settings.write_text(
    text,
    encoding="utf-8",
)

# Ensure current V63B context processor exists.
cp_file = Path("apps/dashboard/context_processors.py")

if not cp_file.exists():
    raise SystemExit(
        "ERROR: falta apps/dashboard/context_processors.py. "
        "Aplique primero V63B."
    )

# Make clause rows editable: add req.id if the current selector uses req.
selector = Path("apps/dashboard/selectors.py")
stext = selector.read_text(encoding="utf-8")
sbackup = selector.with_name(
    selector.name + ".before_v64.bak"
)

if not sbackup.exists():
    sbackup.write_text(
        stext,
        encoding="utf-8",
    )

needle = '"source_row": req.source_row,'
if needle in stext and '"id": str(req.id),' not in stext:
    stext = stext.replace(
        needle,
        '"id": str(req.id),\n                ' + needle,
        1,
    )

selector.write_text(
    stext,
    encoding="utf-8",
)

# Add edit button to clause requirement rows if absent.
clause = Path("templates/dashboard/clause_detail.html")

if clause.exists():
    ctext = clause.read_text(
        encoding="utf-8"
    )

    cbackup = clause.with_name(
        clause.name + ".before_v64.bak"
    )

    if not cbackup.exists():
        cbackup.write_text(
            ctext,
            encoding="utf-8",
        )

    if "Editar requisito" not in ctext:
        anchor = '<td class="req-label">{ row.label }</td>'

        replacement = (
            '<td class="req-label">'
            '{ row.label }'
            '<div style="margin-top:5px;">'
            '<a class="btn-light" '
            'href="{% url \'dashboard:entity_edit\' '
            '\'requisitos-iso\' row.id %}">'
            'Editar requisito</a>'
            '</div>'
            '</td>'
        )

        if anchor in ctext:
            ctext = ctext.replace(
                anchor,
                replacement,
                1,
            )

    clause.write_text(
        ctext,
        encoding="utf-8",
    )

print("")
print("V64 instalada.")
print("Incluye: shell único, CRUD global, relaciones navegables,")
print("activos/riesgos/incidentes visibles, organización dinámica,")
print("Anexo A editable y Dashboard 2026 con render especializado.")
